package com.mycompany.greenbasket;
import java.io.*;import java.util.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;
@WebServlet("/CartServlet") public class CartServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession ss=r.getSession();Map<Integer,Integer> cart=(Map<Integer,Integer>)ss.getAttribute("cart");if(cart==null){cart=new LinkedHashMap<>();ss.setAttribute("cart",cart);}try{int id=Integer.parseInt(r.getParameter("productId"));String a=r.getParameter("action");if("remove".equals(a))cart.remove(id);else{int q=Math.max(1,Integer.parseInt(r.getParameter("quantity")));cart.put(id,q);}}catch(Exception ignored){}s.sendRedirect(r.getContextPath()+("checkout".equals(r.getParameter("next"))?"/checkout.jsp":"/cart.jsp"));}}
